export function composition(s,dish,modId=''){
 const mod=dish.modifications?.find(m=>m.id===modId&&m.reviewed);
 const roots=dish.recipe.filter(r=>!mod?.remove.includes(r.ingredient)).map(r=>r.ingredient).concat(mod?.add||[]);
 const nodes=[];const walk=(id,path,seen)=>{const i=s.ingredients.find(x=>x.id===id);if(!i){nodes.push({id,name:'Missing ingredient',path:[...path,'Missing ingredient'],unknown:true});return;}if(seen.includes(id)){nodes.push({id,name:i.name,path:[...path,i.name],unknown:true});return;}const next=[...path,i.name];nodes.push({...i,path:next,unknown:!i.verified});for(const sub of i.subs)walk(sub,next,[...seen,id]);};for(const id of roots)walk(id,[dish.name],[]);return nodes;
}
export function hasCycle(ingredients){const map=new Map(ingredients.map(i=>[i.id,i.subs]));const visit=(id,path)=>{if(path.includes(id))return true;return(map.get(id)||[]).some(x=>visit(x,[...path,id]));};return ingredients.some(i=>visit(i.id,[]));}
export function fingerprint(s,o,item){const d=s.dishes.find(x=>x.id===item.dish);const t=s.tables.find(x=>x.id===o.table);return JSON.stringify({dish:d,composition:d?composition(s,d,item.mod):[],areas:s.areas.filter(a=>d?.areas.includes(a.id)),diners:t?.diners.filter(x=>item.diners.includes(x.id)),mod:item.mod,notes:item.notes,procedure:s.settings.procedure,catalog:s.allergens});}
export function check(s,o,item){
 const dish=s.dishes.find(x=>x.id===item.dish),table=s.tables.find(x=>x.id===o.table),alerts=[];
 const add=(type,diner,restriction,trigger,path,detail)=>alerts.push({id:`${type}-${diner?.id}-${restriction}-${path.join('/')}`,type,diner:diner?.name||'Unassigned diner',dinerId:diner?.id,table:table?.name||'Unknown table',dish:dish?.name||'Unknown dish',variant:dish?.modifications?.find(m=>m.id===item.mod)?.name||'Standard recipe',restriction,trigger,path,detail});
 if(!dish){add('incomplete',null,'Missing dish','Deleted recipe',[],'Recipe no longer exists.');return alerts;}
 const nodes=composition(s,dish,item.mod);
 const diners=table?.diners.filter(d=>item.diners.includes(d.id))||[];
 if(!diners.length)add('incomplete',null,'Diner assignment missing','No diner',[dish.name],'Assign the dish to a diner.');
 if(diners.length!==item.diners.length)add('incomplete',null,'Diner record missing','Missing diner',[dish.name],'A selected diner no longer exists.');
 for(const diner of diners){
 if(diner.state==='notAsked')add('incomplete',diner,'Not yet asked','Declaration missing',[dish.name],'Ask the diner and explicitly record their declaration.');
 if(diner.state==='declared'&&!diner.restrictions.length&&!diner.notes)add('incomplete',diner,'Declaration incomplete','No structured restriction',[dish.name],'Record at least one restriction or explicit no restrictions.');
 if(diner.notes.trim())add('incomplete',diner,'Free-text declaration','Manual review',[dish.name],'Free text has not been checked automatically: '+diner.notes);
 if(!dish.verified)add('incomplete',diner,'Recipe awaiting verification',dish.name,[dish.name],'Recipe information needs review.');
 if(item.mod&&!dish.modifications.some(m=>m.id===item.mod&&m.reviewed))add('incomplete',diner,'Unreviewed modification','Variant unavailable',[dish.name],'Only configured and reviewed modifications are permitted.');
 for(const n of nodes){if(n.unknown)add('incomplete',diner,'Composition awaiting verification',n.name,n.path,'Current supplier or composition information is incomplete.');
 for(const r of diner.restrictions){const label=(r.target==='allergen'?s.allergens:s.ingredients).find(x=>x.id===r.id)?.name||`Archived restriction (${r.id})`;const restriction=`${r.type}: ${label}`;
 if(r.target==='ingredient'&&r.id===n.id)add('direct',diner,restriction,n.name,n.path,'Contains the declared ingredient.');
 for(const [prop,type]of [['contains','direct'],['may','potential'],['cross','potential']])if(r.target==='allergen'&&n[prop]?.includes(r.id))add(type,diner,restriction,n.name,[...n.path,label],prop==='contains'?'Contains an associated allergen.':prop==='may'?'Supplier indicates may contain.':'Possible ingredient cross-contact.');
 }
 }
 for(const areaId of dish.areas){const area=s.areas.find(x=>x.id===areaId);if(!area||!area.verified)add('incomplete',diner,'Equipment information awaiting verification',area?.name||'Missing preparation area',[dish.name,area?.name||areaId],'Preparation procedure needs verification.');for(const r of diner.restrictions)if(r.target==='allergen'&&area?.allergens.includes(r.id))add('potential',diner,`${r.type}: ${s.allergens.find(a=>a.id===r.id)?.name||r.id}`,area.name,[dish.name,area.name,s.allergens.find(a=>a.id===r.id)?.name||r.id],area.notes);}
 for(const r of diner.restrictions)if(r.target==='allergen'&&dish.cross.includes(r.id))add('potential',diner,`${r.type}: ${s.allergens.find(a=>a.id===r.id)?.name||r.id}`,'Dish cross-contact',[dish.name,'Dish cross-contact',r.id],'Dish-level cross-contact remains after ingredient removal.');
 }
 const fp=fingerprint(s,o,item);const prior=item.reviews||[];
 if(prior.length&&!prior.some(r=>!r.invalidated&&r.fingerprint===fp))add('incomplete',diners[0],'Previous review invalidated','Fresh kitchen review required',[dish.name,'Review record'],'Relevant information changed after the last kitchen review. Record a new assessment using the current composition.');
 return alerts;
}
export const blocked=(s,o,i)=>check(s,o,i).length>0;
export function snapshot(s,o,i){return{at:new Date().toISOString(),fingerprint:fingerprint(s,o,i),dish:clone(s.dishes.find(d=>d.id===i.dish)||null),composition:s.dishes.find(d=>d.id===i.dish)?composition(s,s.dishes.find(d=>d.id===i.dish),i.mod):[],diners:clone(s.tables.find(t=>t.id===o.table)?.diners.filter(d=>i.diners.includes(d.id))||[]),areas:clone(s.areas),allergens:clone(s.allergens),procedure:s.settings.procedure,variant:i.mod,findings:check(s,o,i)};}
export function reconcile(s){for(const o of s.orders)for(const i of o.items){if(['served','canceled'].includes(i.status))continue;const fp=fingerprint(s,o,i);for(const r of i.reviews||[])if(r.fingerprint!==fp)r.invalidated=true;
 const last=i.snapshots?.at(-1);if(!last||last.fingerprint!==fp){i.snapshots??=[];i.snapshots.push(snapshot(s,o,i));if(last&&i.reviews?.length)i.requested=true;}
 if(blocked(s,o,i)&&i.submitted)i.status='awaiting review';
 else if(!blocked(s,o,i)&&i.status==='awaiting review')i.status='received';
}}
export function audit(s,role,action,entity,before,after){s.history.unshift({id:uid('event'),at:new Date().toISOString(),author:(s.users.find(u=>u.role===role&&u.active)?.name||'Demo user')+' · '+role,action,entity,before:clone(before??null),after:clone(after??null)});}
export function allow(role,action){const perms={Waitstaff:['table','diner','order','request'],Kitchen:['review','transition','request'],Administration:['catalog','settings','table','diner','order','request','review','transition','reset']};if(!perms[role]?.includes(action))throw Error('This demonstration role cannot perform that action.');}
export function submit(s,o,role){allow(role,'order');reconcile(s);for(const i of o.items){if(i.submitted||i.status==='canceled')continue;const d=s.dishes.find(d=>d.id===i.dish);if(d?.status!=='available')throw Error('An unavailable dish must be removed before submission.');i.submitted=true;i.status=blocked(s,o,i)?'awaiting review':'received';i.requested=blocked(s,o,i);i.snapshots.push(snapshot(s,o,i));}audit(s,role,'Order sent · blocked dishes separated',`#${o.id}`,null,o);}
export function transition(s,o,i,next,role){allow(role,'transition');reconcile(s);if(!i.submitted)throw Error('Send this dish to the kitchen first.');const edges={'received':['in preparation','canceled'],'awaiting review':['canceled'],'in preparation':['ready','canceled'],'ready':['served','canceled']};if(!edges[i.status]?.includes(next))throw Error('This status transition is not available.');if(['in preparation','ready','served'].includes(next)&&blocked(s,o,i))throw Error('Unresolved dietary findings block preparation.');const old=i.status;i.status=next;audit(s,role,'Preparation status updated',`${o.id} / ${i.id}`,old,next);}
export function review(s,o,i,outcome,notes,role){allow(role,'review');if(!notes.trim())throw Error('Record the composition, procedure and reason for this review.');const r={id:uid('review'),at:new Date().toISOString(),author:(s.users.find(u=>u.role===role&&u.active)?.name||'Demo reviewer'),outcome,notes,fingerprint:fingerprint(s,o,i),snapshot:snapshot(s,o,i),invalidated:false};i.reviews.push(r);s.reviews.unshift({...r,order:o.id,item:i.id});if(outcome==='Cannot prepare under the requested conditions')i.status='canceled';i.requested=false;audit(s,role,'Kitchen review recorded',`${o.id} / ${i.id}`,null,r);return r;}
export function saveIngredient(s,value,role){allow(role,'catalog');if(!value.name.trim())throw Error('Ingredient name is required.');if(value.subs.some(id=>!s.ingredients.some(i=>i.id===id)))throw Error('Unknown subingredient.');const prev=s.ingredients.find(i=>i.id===value.id);const next=s.ingredients.filter(i=>i.id!==value.id).concat(value);if(hasCycle(next))throw Error('Circular ingredient relationship prevented.');s.ingredients=next;audit(s,role,'Ingredient composition updated',value.name,prev,value);reconcile(s);}
export function affectedDishes(s,ingredient){return s.dishes.filter(d=>composition(s,d).some(n=>n.id===ingredient));}
export function orderStatus(s,o){const live=o.items.filter(i=>i.status!=='canceled');if(!live.length)return'canceled';if(live.every(i=>i.status==='served'))return'served';if(live.some(i=>i.status==='in preparation'))return'in preparation';if(live.some(i=>i.status==='ready'))return'ready';if(live.some(i=>blocked(s,o,i)))return'awaiting review';if(live.every(i=>i.status==='draft'))return'draft';return'received';}
