export function loadScenario(s,key,role='Waitstaff'){allow(role,'order');const t=s.tables.find(t=>t.id==='table-10');t.session=uid('session');const d1={id:uid('diner'),name:'Diner 1',state:'declared',restrictions:[{type:key==='cross'||key==='intolerance'?'intolerance':'allergy',target:key==='late'?'ingredient':'allergen',id:key==='nested'?'nuts':key==='cross'||key==='intolerance'?'gluten':key==='late'?'oil':'milk'}],notes:''};if(['clear','persistence','unknown'].includes(key)){d1.state='none';d1.restrictions=[];}t.diners=[d1];if(key==='shared')t.diners.unshift({id:uid('diner'),name:'Diner 2',state:'none',restrictions:[],notes:''});
const dish=({direct:'burrata',nested:'burrata',cross:'fries',unknown:'salad',intolerance:'pesto-pasta',shared:'burrata',modification:'risotto',late:'chicken',recipe:'chicken',clear:'chicken',partial:'burrata',persistence:'chicken'})[key];
if(key==='late'){d1.state='none';d1.restrictions=[];}
const o={id:String(Math.max(1043,...s.orders.map(x=>+x.id))+1),table:t.id,created:new Date().toISOString(),scenario:key,items:[{id:uid('item'),dish,diners:t.diners.map(x=>x.id),quantity:1,mod:'',notes:'',status:'draft',submitted:false,requested:false,reviews:[],snapshots:[]}]};if(key==='partial')o.items.push({...clone(o.items[0]),id:uid('item'),dish:'chicken'});s.orders.unshift(o);if(['late','recipe'].includes(key)){o.items[0].status='received';o.items[0].submitted=true;review(s,o,o.items[0],'Reviewed preparation proposal','Original composition reviewed against the current diner declaration.','Administration');}reconcile(s);audit(s,role,'Sample scenario loaded',scenarios.find(x=>x[0]===key)?.[1],null,o.id);return o;}
